window.FLASH_PUBLICOS = [{"id":"LF176","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? Esclarecemos que, entre as competências do órgão, inclui‐se a execução de ações de controle e avaliação com vistas a monitorar o Sistema de Habitação do Distrito Federal.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CODHAB/QUADRIX/ASSISTENTE/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF177","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? As comunicações oficiais requerem o uso do padrão culto da língua, o que implica o emprego de linguagem rebuscada.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"UFSC/ASSISTENTE/UFSC/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF178","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? Os textos oficiais devem ser isentos de interferências pessoais em sua elaboração.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"UFSC/ASSISTENTE/UFSC/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF195","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? Informamos que Vossa Senhoria, tem prazo de trinta dias à contar da data do recebimento deste ofício para prestar os devindos esclarecimentos quanto o exercício ilegal da medicina.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/ASSISTENTE/CRM-AC/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF196","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? O expediente denominado ofício é apropriado como forma de comunicação entre unidades administrativas de um mesmo órgão.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/ANALSITA/MP-CE/2020/Q1219352 · selecionado via apostila Gran Cursos Online"},{"id":"LF197","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? Em uma correspondência oficial destinada a um procurador-geral de estado, o vocativo a ser empregado é Excelentíssimo Senhor Procurador-Geral.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/ANALISTA/MP-CE/2020/Q1219349 · selecionado via apostila Gran Cursos Online"},{"id":"LF198","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? Nas comunicações oficiais para autoridade de hierarquia superior à do remetente, deve-se utilizar, exceto para o presidente da República, o fecho “Respeitosamente,”.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DEPEN/AGENTE/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF199","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? De acordo com a última edição do MRPR, a distinção entre aviso, memorando e ofício foi abolida, passando-se a adotar o termo ofício como única nomenclatura para todos os expedientes, com o objetivo de uniformizá-los.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DEPEN/AGENTE/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF200","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? Na identificação do signatário de uma comuni - cação oficial destinada a uma pessoa do sexo feminino, dispensa-se flexão de gênero no nome do cargo.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PRF/POLICIAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF201","a":"lp","t":"Redação Oficial (Manual da Presidência, 3ª ed.)","f":"Certo ou errado? O vocativo, nas comunicações oficiais, deverá ser sempre seguido de vírgula.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PRF/POLICIAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF202","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O conjunto de documentos produzidos e acumulados pelo servidor integrará o arquivo de sua instituição, desde que o suporte da informação seja físico.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2572724/QUADRIX/CFO/AG. OPERACIONAL/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF203","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Denomina-se arquivo o conjunto de documentos oficialmente produzidos e recebidos por um governo ou uma organização, no decorrer de suas atividades, e arquivados e conservados para efeitos futuros.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2460036/QUADRIX/CRC-PR/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF204","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo pode ser entendido como um conjunto de documentos oficialmente produzidos e recebidos por um governo, uma organização ou uma firma, no decorrer de suas atividades, arquivados e conservados por si e seus sucessores para efeitos futuros.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2577610/QUADRIX/CREME-RN/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF205","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo pode ser entendido como a reunião de documentos conservados, com vistas à utilidade que poderão oferecer futuramente.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2680379/QUADRIX/CRESS 24ª REG-AP/AG. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF206","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O termo “arquivo” não pode ser usado para designar o móvel para guarda de documentos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2680382/QUADRIX/CRESS 24ª REG-AP/AG. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF207","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O termo “arquivo” também pode ser usado para designar o órgão governamental ou institucional cujo objetivo seja o de guardar e conservar a documentação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2680387/QUADRIX/CRESS 24ª REG-AP/AG. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF208","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? De acordo com o conceito de arquivo, os documentos, além de serem produzidos pela instituição, podem também ser recebidos por ela.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2680389/QUADRIX/CRESS 24ª REG-AP/AG. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF209","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo pode ser defini - do como a acumulação ordenada de documentos, em sua maioria textuais, criados por uma instituição ou pessoa, no curso de sua atividade, e preservados para a consecução de seus objetivos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2680392/QUADRIX/CRESS 24ª REG-AP/AG. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF210","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O conceito moderno de arquivo pode ser definido como o conjunto de documentos produzidos por um governo, uma organi - zação ou uma firma, no decorrer de suas atividades, arquivados e conservados por si e seus sucessores para efeitos futuros.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2523753/QUADRIX/CRMV-RJ/AUX. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF211","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O documento de arquivo é aquele produzido e recebido pelos órgãos do poder público, no desempenho de suas atividades.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2592422/QUADRIX/CRO-RS/TELEFONISTA/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF212","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo como objeto físico é aquele considerado apenas como conjuntos documentais produzidos e recebidos pelas entidades públicas ou privadas no exercício de suas funções.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFT/ASSIST .ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF213","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é a acumu - lação ordenada dos documentos, em sua maioria textuais, criados por uma instituição ou pessoa, no curso de sua atividade, e preservados para a consecução de seus objetivos, visando à utilidade que poderão oferecer no futuro.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRECI 14ª REG-MS/ASSIST . ADMINISTRATIVO/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF214","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A palavra arquivo pode ser adequadamente utilizada para designar o órgão governamental ou institucional que tem como objetivo a guarda e a conservação dos documentos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFONO 3ª REGIÃO-PR-SC/ASSIST . ADM. JR/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF215","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? À medida que as atividades e funções são desenvolvidas nas instituições, os documentos de arquivo vão sendo acumulados naturalmente.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS 13ª REG-PB/ASSIST . ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF216","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O conceito moderno de arquivo o define como um depósito de papéis de qualquer espécie, tendo sempre relação com os direitos das instituições ou dos indivíduos, de modo a estabelecer ou a reivindicar direitos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS 18ª REG-SE/ASSIST . ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF217","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é o conjunto de documentos oficialmente produzidos e recebidos por um governo, uma organização ou uma firma, no decorrer de suas atividades, arquivados e conservados por si e seus sucessores, para efeitos futuros.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFO-DF/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF218","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é um conjunto de documentos produzidos e acumulados por uma entidade coletiva, pública ou privada, que tem por finalidade a custódia, o processamento técnico, a conservação e o acesso a documentos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRN 2ª REG/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF219","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Um conjunto de documentos acumulados a partir das funções e atividades de instituição / órgão / organização pode ser chamado de arquivo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS-SC/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF220","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Quando se encontra um conjunto de documentos que foi resultado do desenvolvimento das atividades de uma organização, é possível entendê-lo como arquivo institucional.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRN 9ª REG/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF221","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de arquivo constituem a evidência ou prova da execução de uma atividade dentro da instituição.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRBM 6ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF222","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O cumprimento de uma atividade ou função na institui - ção é o que dá origem aos documentos de arquivo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRN 10ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF223","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo pode ser pessoal ou institucional e é formado a partir da necessidade que pessoas (físicas ou jurídicas) têm de guardar documentos que comprovem as atividades que desenvolveram ao longo da vida.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRF-RS/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF224","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? É considerado como arquivo o conjunto de documentos oficiais gerados pelos governos federais, estaduais e municipais, no âmbito da Administração Pública, que servem aos interesses governamentais.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-DF/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF225","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A palavra “arquivo” designa diferentes significados: conjunto de documentos; o móvel em que se guardam esses documentos; a sala ou o lugar onde tais documentos estão armazenados ou ainda conjunto de dados ou informações registradas em meio digital, identificado por nome.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-TO/ANAL. CONTÁBIL/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF226","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é o conjunto de documentos que, dependendo da natureza ou do suporte, são reunidos por acumulação ao longo das atividades de pessoas físicas ou jurídicas, públicas ou privadas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF 11ª REG/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF227","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os conjuntos de atas de reuniões da Diretoria, de projetos de pesquisa e de relatórios de atividades, mais os conjuntos de prontuários médicos, de boletins de notas, de fotografias etc., constituem-se o arquivo de uma Unidade, por exemplo, e devem naturalmente refletir as suas atividades.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF 11ª REG/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF228","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O termo arquivo pode ser explicitado como o conjunto de documentos produzidos e recebidos por entidades públicas ou privadas, ou ainda por indivíduos, no decorrer de suas atividades e conservados por si ou por quem lhes faça a vez, para eventual necessidade futura.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/SERPRO/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF229","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é o conjunto de documentos oficialmente produzidos e recebidos por um governo, organização, firma ou pessoa, no decorrer de suas atividades, arquivados e conservados por si e seus sucessores para efeitos futuros.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/FUNDAÇÃO DO ABC/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF230","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A expressão arquivo é utilizada com vários sig - nificados, dentre os quais, um conjunto de documentos ou o lugar ou móvel onde se guardam esses documentos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/FUNDAÇÃO DO ABC/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF231","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O termo documento é utilizado para indicar toda informação registrada em um suporte material, suscetível de consulta, estudo, prova e pesquisa, pois comprova fatos, fenômenos, formas de vida e pensamentos do homem numa determinada época ou lugar.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRF-SP/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF232","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Dentro de uma entidade que produz bens ou serviços, a informação é uma ideia ou conhecimento. Para que seja transmitida necessita de um suporte que é o meio no qual a informação é registrada. No momento em que esse registro ocorre em um suporte, origina-se um documento.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRP-18ª REG/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF233","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é a designação genérica de um conjunto de docu - mentos produzidos e recebidos por uma pessoa física ou jurídica, pública ou privada, acu - mulados e conservados por essas pessoas ou por seus sucessores, para fins de prova ou informação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV/ES/2008 · selecionado via apostila Gran Cursos Online"},{"id":"LF234","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? É correto afirmar que o valor de informação é uma qualidade que o documento possui, independentemente de seu suporte ou de sua natureza.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2836004/QUADRIX/PROCON-DF/ANAL. ARQUIVOLOGIA/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF235","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Documento é toda informação registrada em um suporte material e suscetível de consulta.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2625815/QUADRIX/CRC-MG/AUX. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF236","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Documento é a junção do suporte e de dados significativos e informações.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2625818/QUADRIX/CRC-MG/AUX.ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF237","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A característica suporte cor - responde ao material no qual as informações são registradas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFITO 6ª REG-CE/RECEPCIONISTA/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF238","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Define-se documento como o registro de uma informação que depende da natureza do suporte que a contém.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2545736/QUADRIX/CREME-GO/AUX. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF239","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Documento é toda informação registrada em um suporte material, suscetível de consulta, estudo, prova e pesquisa, pois comprova fatos, fenômenos, formas de vida e pensamentos do homem em determinada época ou determinado lugar.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2577609/QUADRIX/CREME-RN/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF240","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Na automação do arquivo, o suporte é o próprio computador, bem como os bancos de dados nos quais são armazenados regis - tros sobre determinado assunto.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2537639/QUADRIX/CRM-PI/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF241","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Suporte é o material físico no qual a informação é registrada.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2398265/QUADRIX/CRO-ES/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF242","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O documento é o material físico no qual a informação está registrada, independentemente da natureza da informação.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-AC/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF243","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A definição de arquivo não sofre alteração de acordo com seu suporte, mesmo sendo ele digital.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRECI 5ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF244","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Um DVD virgem é um tipo de suporte, mas pode ser, também, um tipo de documento.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRECI 5ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF245","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O suporte consiste no material físico no qual a informação é registrada.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRM-PR/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF246","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é um conjunto de documentos, produzidos e acumulados por uma entidade coletiva, pública ou privada, pessoa ou família no desempenho de suas atividades, independentemente da natureza do suporte.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRA-GO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF247","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é o conjunto de documentos que, independente - mente da natureza ou do suporte, são reunidos por acumulação ao longo das atividades de pessoas físicas ou jurídicas, públicas ou privadas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-MT/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF248","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Também fazem parte do arquivo documentos cujas informações são registradas em suportes diferentes do papel (discos, filmes e fitas, por exemplo).","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF-11ª REG/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF249","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos são os registros de uma informação independentemente da natureza do suporte que a contém.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/FUND.ABC/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF250","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é um conjunto de documentos, organicamente acumulados, produzidos ou recebidos por pessoa física e instituições públicas ou privadas, em decorrência do exercício de atividade específica, qualquer que seja o suporte da informação ou a natureza do documento.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF-3ª REG-SC/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF251","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo representa o conjunto de documentos produzidos e recebidos pela instituição (órgãos públicos, instituições de caráter público ou entidades privadas, ou ainda pessoa física) no curso de sua atividade, qualquer que seja o suporte da informação ou a natureza dos documentos e que foram preservados para servirem como fonte de informação para a execução de suas atividades.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRF-SP/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF252","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo e o conjunto de documentos que, independen - temente da natureza ou do suporte, são reunidos por acumulação ao longo das atividades da entidade.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-SP/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF253","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A função primordial dos arquivos é restringir o acesso às informações contidas nos documentos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFITO 6ª REG-CE/RECEPCIONISTA/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF254","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo de uma instituição funciona como o guardião das informações ali existentes.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2577607/QUADRIX/CREME-RN/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF255","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A adoção de técnicas arquivísticas adequadas permite não apenas a localização eficiente da informação desejada, mas também a economia de recursos para a instituição.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2577612/QUADRIX/CREME-RN/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF256","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo possui como finali - dade a garantia de preservação de documentos, por meio de formas adequadas de acondicionamento.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2577614/QUADRIX/CREME-RN/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF257","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A recepção, a organização e a preser - vação de documentos são atividades específicas do arquivo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2167182/QUADRIX/CFT/ASSIST . ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF258","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Após arquivado, um documento não pode ser solicita - do novamente.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF 13ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF259","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A função básica do arquivo é a preservação da memória da instituição.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-AC/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF260","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O principal objetivo do arquivo é disponibilizar as informações contidas nos documentos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFO-DF/TÉC.ARQUIVO/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF261","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Um dos tipos de público que faz uso do arquivo é o cidadão comum.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFO-DF/TÉC.ARQUIVO/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF262","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A disponibilidade das informações contidas no acervo documental é a função básica do arquivo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRN 3ª REG/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF263","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Basicamente, a função do arquivo é guardar e organizar os documentos acumulados pela instituição a que pertencem, de forma a facilitar sua localiza - ção, quando necessário. Uma boa organização dos arquivos permite que a instituição ganhe tempo e otimize seus recursos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-RR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF264","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A função do arquivo é guardar e organizar os documentos acumulados pela instituição a que pertence, de forma a facilitar a localização desses docu - mentos, quando necessário.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF265","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Uma boa organização dos arquivos permite que a instituição ganhe tempo e otimize seus recursos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF266","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A função do arquivo, seja na modalidade física, seja na eletrônica, é de permitir uma consulta rápida e eficaz aos documentos sob pesquisa.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF267","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo pode ser conceituado como “conjunto de documen - tos oficialmente produzidos e recebidos por um governo, organização ou firma, no decorrer de suas atividades, arquivados e conservados por si e seus sucessores para efeitos futuros”.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-GO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF268","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A função de um arquivo e guardar a documentação e principalmente fornecer aos interessados as informações contidas em seu acervo de maneira rápida e segura.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRF-7ª REG/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF269","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A função primordial dos arquivos é disponibilizar as informações contidas nos documentos para a tomada de decisão e comprovação de direitos e obrigações que se efetivarão se os documentos estiverem corretamente classificados e organizados.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-SP/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF270","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Uma das definições de arquivo é que este é um conjunto de documentos criados e também recebidos por uma entidade, que são mantidos de uma maneira ordenada para que sirvam, quando necessário, como fonte de informação para a execução das atividades dessa entidade.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRP-9ª REG/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF271","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Seja na Indústria, como nas entidades comerciais ou prestadoras de serviço, os serviços de arquivo devem ser organizados com cuidado, a fim de não só serem conservados e protegidos os papéis e documentos em geral, mas também para que possam ser localizados a qualquer momento.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRP-9ª REG/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF272","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo possui duas finalidades. A primeira é administrativa, tendo uma função mantenedora de documentos. A se - gunda finalidade é histórica, preservando, por meio de sua documentação, aspectos históricos relativos à organização e à sociedade em geral.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2354192/QUADRIX/CRP 19ª REG-SE/PSICÓLOGO/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF273","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A importância do arquivo para a instituição está ligada ao aumento expressivo do volume de documentos que utiliza no exercício de suas atividades e à necessidade de se estabelecerem critérios de guarda e de eliminação de documentos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2680390/QUADRIX/CRESS 24ª REG-AP/AG.ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF274","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A finalidade de um arquivo é tornar disponíveis as informações do acervo e a função do arquivo é servir à administração e, no decorrer do tempo, fundamentar o conhecimento histórico.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRBM 4ª REG-PA/AG. ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF275","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os arquivos são criados para preservar a memória da instituição.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS 13ª REG-PB/ASSIST . ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF276","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A finalidade de um arquivo é apenas a de servir à administração de uma instituição pública.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFO-DF/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF277","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo é criado para a preservação da memória da instituição ou da pessoa física que o acumulou.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF 11ª REG/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF278","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A principal finalidade do arquivo é servir de memória para a comunidade.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF279","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? É função do arquivo, na sua origem, atender a objetivos históricos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRBM 6ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF280","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os arquivos nascem com a finalidade de se - rem celeiros da história.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFO-DF/TÉC. ARQUIVO/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF281","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os arquivos possuem uma importância inestimável para a memória e construção histórica de um país.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CONTER/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF282","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Ao organizar os documentos, o arquivo atende, fundamentalmente, a duas finalidades distintas: à administração e à história.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRB/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF283","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo guarda e organiza os documentos com objetivos funcionais (atender à administração é a sua principal finalidade).","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF284","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A principal finalidade dos arquivos é servir à administração no momento oportuno de uma consulta ou pesquisa.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF285","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A principal finalidade do arquivo é servir como fonte de consulta à administração, pois é constituído, em sua essência, dos documentos produzidos e dos documentos recebidos pela entidade mantenedora do acervo, podendo, ao longo do tempo, servir como elemento de história.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS 23ª REG-RO/AG.ADM/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF286","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A principal finalidade dos arquivos é servir a administração, constituindo-se, com o decorrer do tempo, em base do conhecimento da história.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-SE/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF287","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O documento de arquivo está contido em um conjunto material, em sua maioria impresso, disposto ordenadamente para estudo, pesquisa e consulta.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2625811/QUADRIX/CRC-MG/AUX.ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF288","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de biblioteca são aqueles contidos em uma instituição de interesse público criada com a finalidade de conservá- -los e colocá-los à disposição do público.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2625813/QUADRIX/CRC-MG/AUX. ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF289","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Na biblioteca, os documentos são colecionados de fontes diversas e adquiridos por compra, doação ou permuta.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2625814/QUADRIX/CRC-MG/AUX.ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF290","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Na biblioteca, os documentos são produzidos e conservados com objetivos funcionais.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2625817/QUADRIX/CRC-MG/AUX.ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF291","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de museu são advindos das funções naturais de um órgão.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"Q2625819/QUADRIX/CRC-MG/AUX.ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF292","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Uma biblioteca pode receber doações de documentos de outros países.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2460032/QUADRIX/CRC-PR/ASSIST . ADM/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF293","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Diferentemente das bibliotecas e dos centros de documentação, que formam seus acervos a partir da sistemática de coleção, os documentos de arquivo do setor em que o servidor labora se formam por meio do processo de acumulação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"Q2572728/QUADRIX/CFO/AG. OPERACIONAL/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF294","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O museu é considerado como uma instituição de interesse público, cujos objetivos principais são a informação e o entretenimento, tendo finalidades cultural e didática.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS 18ª REG-SE/ASSIST . ADM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF295","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo é formado por todo tipo de documento acu - mulado pela entidade, incluindo os documentos tridimensionais e digitais.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF 20ª REG/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF296","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de arquivo diferem dos documentos de biblioteca por não serem produzidos em vários exemplares.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRESS-GO/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF297","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo é uma coleção de documentos acumulados por uma pessoa jurídica, pessoa física ou família e de documentos considerados como de referência para a pessoa ou instituição.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF298","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os valores culturais dos documentos de arquivo são uma conexão direta com as atividades funcionais de uma organização.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF299","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de arquivo e os documentos de biblioteca são diferentes quanto ao modo por meio do qual se originaram e quanto ao modo por meio do qual entraram para as respectivas custódias.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF300","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O material impresso (jornais, folhetos etc.), normalmente fica sob a responsabilidade dos arquivos, mas, em algumas situações, pode adquirir um caráter biblioteconômico.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF301","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo é composto por documentos produzidos em um único exemplar ou em limitado número de cópias.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF302","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo é colecionado de várias fontes e adquirido sempre por compra ou doação.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFBIO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF303","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O arquivo não é objeto de coleção; ele provém das atividades da instituição ou da pessoa.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRBM 6ª REG/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF304","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? A atividade geradora dos documentos de arquivo é a cultural.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRP 2A REG-PE/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF305","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? O conjunto material, em sua maioria impres - so, disposto ordenadamente para estudo, pesquisa e consulta pode ser chamado de arquivo.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CFO-DF/TÉC. ARQUIVO/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF306","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Arquivo é a coleção de documentos composta durante o desenvolvimento das atividades de uma instituição.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRN 3ª REG/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF307","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Informações orgânicas (que comprovam as atividades da instituição e são criadas em decorrências destas atividades) são organizadas e conservadas nos arquivos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF308","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de arquivo são produzidos pela própria insti - tuição, no desempenho de suas atividades, ou recebidos de outras instituições, sempre num contexto administrativo ou funcional.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF309","a":"ce","t":"Arquivologia: conceitos e gestão de documentos","f":"Certo ou errado? Os documentos de arquivo são escolhidos pela instituição e adquiridos conforme sua conveniência, formando coleções (vários exemplares). Tal aquisição se dá, normalmente, por meio da compra do material escolhido, ou, ainda, de doações efetuadas por usuários ou mesmo a permuta (troca) com instituições educacionais.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRO-PR/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF331","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? As transferências de pessoal dentro da organização, as promoções e os planos de carreira são modalidades de recrutamento interno.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUDITOR DE CONTROLE EXTERNO/TCE-PA/ADMINISTRATIVA/ ADMINISTRAÇÃO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF332","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Do ponto de vista de aplicação, as organizações devem recorrer ao recrutamento externo, uma vez que o mercado de recursos humanos dispõe de candidatos mais capacitados para atuarem nas empresas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUDITOR DE CONTROLE EXTERNO/TCE-PA/PLANEJAMENTO/ ADMINISTRAÇÃO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF333","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? A introdução de novos profissionais nas organizações é entendida como uma desvantagem do processo de recrutamento externo, uma vez que novos contratados tendem a desestabilizar culturas organizacionais consolidadas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUDITOR DE CONTROLE EXTERNO/TCE-PA/PLANEJAMENTO/ ADMINISTRAÇÃO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF334","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Os objetivos do processo de recrutamento incluem atrair candidatos qualificados para uma organização.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUDITOR DE CONTROLE EXTERNO/TCE-PA/PLANEJAMENTO/ ADMINISTRAÇÃO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF335","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? O recrutamento externo privilegia os atuais funcionários de uma organização que pretendem mudar de área de trabalho ou ocupação, processo que geralmente ocorre quando um funcionário da sede opta por trabalhar em uma organização subsidiária.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TÉCNICO JUDICIÁRIO/STM/ADMINISTRATIVA/”SEM ESPECIALIDADE”/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF336","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? O impacto na política de remuneração da organização é uma das desvantagens do processo de recrutamento interno.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANALISTA/FUNPRESP/ADMINISTRATIVA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF337","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? A seleção consiste no processo de reunir potenciais candidatos para suprir as necessidades de recursos humanos da organização.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANALISTA/FUNPRESP/ADMINISTRATIVA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF338","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? A busca por profissionais qualificados que atuam em cargos ou postos de trabalho mais sofisticados e especializados no mercado, por meio de sítios de empregos, anúncios em jornais, headhunter, entre outras estratégias, exemplifica como as organizações fazem uso do recrutamento geral de pessoas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ASSISTENTE/FUB/ADMINISTRAÇÃO/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF339","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Os índices de retorno de recrutamentos, pela efetividade dos processos de atração e identificação de candidatos no mercado, revelam-se uma ferramenta de gestão importante para profissionais de recursos humanos na contratação de pessoas para as organizações.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TECNÓLOGO/FUB/RECURSOS HUMANOS/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF340","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? O recrutamento de pessoal, processo que pode ser interno ou externo, tem por finalidade a captação de recursos humanos para a organização.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ESPECIALISTA EM GESTÃO DE TELECOMUNICAÇÕES/TELEBRAS/ANALISTA SUPERIOR/ADMINISTRATIVO/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF346","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Durante o processo de seleção de pessoas, o profissional de RH utiliza a entrevista de triagem inicial para mensurar as habilidades de um candidato para o trabalho, bem como a capacidade que ele tem de aprender trabalhando.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ASSISTENTE/FUB/ADMINISTRAÇÃO/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF347","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Os candidatos mais aptos aos cargos são pré-selecionados pelos profissionais de recursos humanos por meio de entrevistas, para, posteriormente, serem avaliados em testes psicológicos e de conhecimentos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TECNÓLOGO/FUB/RECURSOS HUMANOS/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF348","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? A análise de currículo, atividade típica de processos de recrutamento de pessoas, busca identificar perfis adequados aos cargos da empresa contratante.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TECNÓLOGO/FUB/RECURSOS HUMANOS/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF356","a":"ce","t":"Trabalho em equipe, relações interpessoais e comunicação","f":"Certo ou errado? Um conflito é uma interferência deliberada, ativa ou passiva, que afeta negativamente a tentativa da outra parte de alcançar seus objetivos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFONO 5/AUXILIAR ADMINISTRATIVO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF357","a":"ce","t":"Trabalho em equipe, relações interpessoais e comunicação","f":"Certo ou errado? Principia-se um conflito quando uma parte percebe que seus interesses foram ou serão frustrados pela outra parte, que está impedindo ou em vias de impedir uma ação importante.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/PGE-PE/ANALISTA ADMINISTRATIVO DE PROCURADORIA/RE - CURSOS HUMANOS/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF358","a":"ce","t":"Trabalho em equipe, relações interpessoais e comunicação","f":"Certo ou errado? Em uma negociação, a melhor alternativa para um acordo negociado (MAANA) representa a situação-limite para a realização de um acordo, ou seja, só é viável negociar se, no mínimo, for possível atingir essa situação no acordo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREF 8/AGENTE DE ORIENTAÇÃO E FISCALIZAÇÃO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF362","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Incluem-se entre as finalidades do processo de TDE a adequação do colaborador à cultura da empresa e a redução de custos na busca por objetivos empresariais.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TÉCNICO DO BANCO CENTRAL DO BRASIL/ÁREA 1/SUPORTE TÉCNICO- ADMINISTRATIVO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF363","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? O treinamento é um processo de assimilação cultural em curto ou médio prazo que produz um estado de mudança no conjunto de conhecimentos, habilidades e atitudes do indivíduo, podendo ser realizado por meio de cursos e oficinas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TÉCNICO DO BANCO CENTRAL DO BRASIL/ÁREA 1/SUPORTE TÉCNICO- ADMINISTRATIVO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF377","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Visando manter-se competitivas, as organizações devem propiciar ambientes que favoreçam o processo de aprendizagem coletiva, pois, a partir dela, a organização pode atingir maior agilidade no processo de resposta organizacional ao ambiente externo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/2024/ANALISTA PLENO I/CNPQ/ADMINISTRAÇÃO DE PESSOAL · selecionado via apostila Gran Cursos Online"},{"id":"LF378","a":"ce","t":"Gestão de pessoas: conceitos e função do órgão de GP","f":"Certo ou errado? Por ter caráter prospectivo, o diagnóstico de necessidades de treinamento permite que as organizações se antecipem a situações que devam ser solucionadas por meio da capacitação de sua força de trabalho, o que implica uma dimensão estratégica para as ações de educação corporativa.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/2024/ANALISTA PLENO I/CNPQ/ADMINISTRAÇÃO DE PESSOAL · selecionado via apostila Gran Cursos Online"},{"id":"LF386","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? Os sucessores da pessoa que causar lesão ao patrimônio público ou enriquecer-se ilicitamente poderão sofrer as consequências das sanções patrimoniais previstas na Lei de Improbidade Administrativa até o limite do valor da herança.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANALISTA JUDICIÁRIO/STJ/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF387","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? O estagiário de órgão público não pode ser sujeito ativo de ato de improbidade administrativa, em virtude do vínculo precário e transitório que mantém com a administração pública.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TJ TJDFT/ADMINISTRATIVA/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF388","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? O rol de condutas tipificadas como atos de improbidade administrativa constante na Lei de Improbidade (Lei n. 8.429/1992) é taxativo.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/DEF PF/DPU/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF389","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? Ao negar publicidade a ato oficial, o servidor público comete ato de improbidade administrativa que atenta contra os princípios da administração pública.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ADMINISTRADOR/MPOG/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF390","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? O dano ao erário, enriquecimento ilícito e a violação de princípio administrativo, se praticados por agente público, são considerados atos de improbidade administrativa.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUD CE/TCE-PA/ADMINISTRATIVA/GESTÃO DE PESSOAS/ 2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF391","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? Entre as sanções para a prática de ato de improbidade administrativa previstas na Lei n. 8.429/1992 inclui-se a suspensão dos direitos políticos, que não se encontra expressamente prevista na CF .","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANA FUNPRESP/ADMINISTRATIVA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF392","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? As penalidades previstas na Lei de Improbidade Administrativa também são aplicadas a não servidores e a quem induza ou concorra para a prática de ato de improbidade ou dele se beneficie de forma direta ou indireta.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUD CE/TCE-PA/PROCURADORIA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF393","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? Para assinar o termo de posse, o servidor deverá apresentar declaração de bens e valores que constituem seu patrimônio e declaração quanto ao exercício de outro cargo, emprego ou função pública.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUD CE/TCE-PA/ADMINISTRATIVA/GESTÃO DE PESSOAS/ 2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF394","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? Agente público que se recusar a prestar a declaração de bens dentro do prazo determinado em lei deverá ser punido com a pena de demissão a bem do serviço público.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUX TEC CE/TCE-PA/INFORMÁTICA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF395","a":"ap","t":"Improbidade administrativa (Lei 8.429/1992 e alterações)","f":"Certo ou errado? Os herdeiros daquele que causar lesão ao patrimônio público estarão sujeitos às cominações legais até o limite do valor da herança.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANA FUNPRESP/ADMINISTRATIVA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF429","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? A integridade consiste na qualidade da informação não modificada, inclusive quanto à origem, ao trânsito e ao destino.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-CE/ASSISTENTE ADMINISTRATIVO/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF430","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? É vedada a cobrança de qualquer valor quando do fornecimento de informações previstas pela Lei n. 12.527/2011 a cidadão interessado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/MMA/ANALISTA/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF431","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? Os prazos da Lei de Acesso à Informação são contados a partir do dia útil seguinte ao da notificação oficial, e a divulgação de informações de interesse público ocorre unicamente por meio impresso.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CGE-RJ/AUDITOR/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF432","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? De acordo com a Lei de Acesso à Informação, os órgãos públicos têm o dever de responder às solicitações de informação dentro de um prazo de 20 dias, prorrogável por mais 10 dias, mediante justificativa expressa, assegurando a efetividade do direito de acesso à informação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"IGEDUC/CÂMARA/MÉDIO/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF433","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? A Lei n. 12.527/2011 resguarda o direito de acesso a informações de qualquer resultado de inspeções e auditorias realizadas por órgão de controle interno no Ministério do Meio Ambiente.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/MMA/ANALISTA AMBIENTAL/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF434","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? O pedido de acesso à informação é prerrogativa privativa da pessoa natural.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-CE/ASSISTENTE/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF435","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? Pela Lei de Acesso à Informação, as entidades privadas sem fins lucrativos que recebem recursos públicos para a realização de ações de interesse público estão isentas de prestar contas sobre como esses recursos são utilizados.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"IGEDUC/CÂMARA/MÉDIO/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF436","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? Quando se tratar de acesso à informação contida em documento cuja manipulação possa prejudicar sua integridade, deverá ser oferecida a consulta de cópia, com a certificação de que esta confere com o original.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRP/PSICOLOGO/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF437","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? De acordo com a LAI, são requisitos indispensáveis para o acesso às informações de interesse público a identificação do requerente, a descrição dos motivos determinantes da solicitação e a especificação da informação requerida.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CAPES/ANALISTA/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF438","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? A Lei de Acesso à Informação estabelece que as solicitações de informações podem ser atendidas em um prazo indeterminado, permitindo que os órgãos públicos definam seus próprios cronogramas de resposta com base em sua carga de trabalho e prioridades administrativas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"IGEDUC/CÂMARA/MÉDIO/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF439","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? As autoridades têm a responsabilidade de garantir o acesso à informação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CGE-RJ/AUDITOR/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF440","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? É proibido negar acesso à informação necessária à tutela judicial ou administrativa de direitos fundamentais.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CAPES/ANALISTA/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF441","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? Conforme a Lei n. 12.527/2011, documento é a unidade de registro de informações, qualquer que seja o suporte ou formato.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/MMA/ANALISTA/2024 · selecionado via apostila Gran Cursos Online"},{"id":"LF442","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? As disposições da Lei de Acesso à Informação não se aplicam às autarquias, uma vez que elas integram a administração pública indireta.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CNMP/ANALISTA/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF443","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? Segundo entendimento do STF , as entidades privadas com fins lucrativos devem dar transparência e publicidade aos recursos recebidos por meio de subvenções, isenções tributárias e, indiretamente, perdão de dívidas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/MPE-SC/PROMOTOR/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF444","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? As autarquias e as fundações públicas estão subordinadas ao regime da Lei n. 12.527/2011 (Lei de Acesso à Informação).","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/SERPRO/ANALISTA/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF445","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? As solicitações de acesso à informação podem ser protocoladas anonimamente pelos cidadãos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/DATAPREV/ANALISTA/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF446","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? É imprescindível que o cidadão interessado preencha requerimento para solicitar informações de interesse coletivo custodiadas pelos órgãos públicos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/T J-ES/ANALISTA JUDICIÁRIO/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF447","a":"ap","t":"LAI (Lei 12.527/2011 e Decreto 7.724/2012)","f":"Certo ou errado? A Lei de Acesso à Informação é de caráter nacional e alcança também os estados e os municípios.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CAU-PATÉCNICO/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF448","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Se um policial rodoviário federal receber ordem verbal de um superior e suspeitar que a determinação seja ilegal, ele poderá deixar de cumpri-la, com base nessa suspeita.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/PRF/PRF/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF449","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? 8.112/1990. Tal conduta poderá acarretar penalidade de demissão ao servidor.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/AAMB/IBAMA/IBAMA/LICENCIAMENTO AMBIENTAL/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF450","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? O item a seguir é apresentada uma situação hipotética seguida de uma assertiva a ser julgada a respeito de aspectos legais a elas relacionados. Um servidor público efetivo que cometeu falta grave no órgão em que trabalhava e se aposentou antes da decisão administrativa final sobre seu processo poderá ter cassada a aposentadoria em caso de condenação com pena de demissão.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/APC/FUNPRESP-EXE/FUNPRESP-EXE/ADMINISTRATIVA/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF451","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Apesar de as instâncias administrativa e penal serem independentes entre si, a eventual responsabilidade administrativa do servidor será afastada se, na esfera criminal, ele for beneficiado por absolvição que negue a existência do fato ou a sua autoria.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AJ ST J/ST J/ADMINISTRATIVA/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF452","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? A demissão será a penalidade disciplinar cabível para o servidor que se recusar a ser submetido a inspeção médica determinada pela autoridade competente.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANA ADM/EBSERH/EBSERH/ADMINISTRAÇÃO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF453","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Servidor público aposentado poderá ter a sua aposentadoria cassada em função de condenação por infração vinculada ao cargo público anteriormente ocupado.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ASSISTENTE ADMINISTRATIVO/FUB/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF454","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? As responsabilidades civil, penal e administrativa do servidor público, ainda que possam ser cumuladas durante a fase de apuração da infração, não poderão resultar em sanções independentes, devido à necessária correspondência entre infração e sanção.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TÉCNICO FUB/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF455","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Considere que, após regular processo administrativo contra servidor vinculado à administração pública unicamente por cargo em comissão, a autoridade julgadora tenha concluído que o servidor cometeu infração punível com a penalidade de suspensão. Nesse caso, a penalidade a ser aplicada será a exoneração de ofício do servidor faltoso.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CADE/2014/AGENTE ADMINISTRATIVO · selecionado via apostila Gran Cursos Online"},{"id":"LF456","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Com referência ao servidor público federal, a responsabilidade administrativa e a penal são independentes entre si, podendo cumular-se, salvo no caso de absolvição criminal que negue a ocorrência do fato ou a sua autoria.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ATA/DPU/DPU/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF457","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Caso o servidor público tenha causado danos ao poder público, a obrigação de reparar tais danos estende-se aos seus sucessores e contra eles será executada, até o limite do valor da herança recebida.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AG ADM/DPU/DPU/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF458","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? 8.112/1990 e na Portaria PGR/MPU n. 98/2017 — Código de Ética e de Conduta do Ministério Público da União (MPU) e da Escola Superior do Ministério Público da União (ESMPU). É cabível penalidade de suspensão ao servidor que reincidir em faltas punidas com advertência.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CESPE/ANA MPU/MPU/APOIO JURÍDICO/DIREITO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF459","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? É dever do servidor público respeitar a hierarquia, respeito esse que veda a ele representar contra comprometimentos da estrutura do poder estatal.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANA ADM/EBSERH/EBSERH/ADMINISTRAÇÃO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF460","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? União Diogo Surdi Nos termos da Lei n. 8.112/1990, os deveres do servidor público incluem representar contra ilegalidade, omissão ou abuso de poder e promover manifestação de apreço no recinto da repartição.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TECNO GP/EBSERH/EBSERH/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF461","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? O servidor responde apenas administrativamente pelo exercício irregular de suas atribuições, o qual pode ensejar a aplicação de penalidade disciplinar — até mesmo de demissão —, que deve, sempre, mencionar o fundamento legal e a causa da sanção.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ASS ADM/EBSERH/EBSERH/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF462","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? A destituição de servidor de cargo em comissão ou de função comissionada não pode ser aplicada como penalidade disciplinar.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AJ TRF1/TRF 1/ JUDICIÁRIA/OFICIAL DE JUSTIÇA AVALIADOR FEDERAL/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF463","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? É proibido ao servidor público atuar como intermediário junto a repartições públicas, salvo quando se tratar de benefícios previdenciários ou assistenciais de parentes até o segundo grau e de cônjuge ou companheiro.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANA/INSS/INSS/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF464","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Nos termos da lei, a obrigação de reparação de dano praticado por servidor público não é extensível aos seus sucessores.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUD CE/TCE-PA/TCE-PA/ADMINISTRATIVA/GESTÃO DE PESSOAS/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF465","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? As sanções civis, penais e administrativas não podem ser cumuladas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUX/FUB/FUB/ADMINISTRAÇÃO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF466","a":"ap","t":"Lei 8.112/1990: provimento, vacância, direitos e vantagens","f":"Certo ou errado? Atrasos constantes no cumprimento da jornada de trabalho podem caracterizar conduta desidiosa, procedimento que, de acordo com o estatuto dos servidores públicos civis da União, pode resultar em demissão.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TÉCNICO ADMINISTRATIVO/MPU/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF481","a":"ce","t":"Processo organizacional: planejamento, direção, comunicação, controle","f":"Certo ou errado? O Decreto-lei n.º 200/1967, na tentativa de modernizar a gestão pública no Brasil, estabeleceu como princípios fundamentais o planejamento, a organização, o treinamento e a direção.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TCE-PA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF482","a":"ap","t":"Governança, integridade, controle e Decreto 9.830/2019","f":"Certo ou errado? O Plano Diretor da Reforma do Aparelho do Estado foi criado na transição entre o governo de Collor e o de Itamar Franco, com a finalidade de aumentar a governança do Poder Executivo.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TCE-PA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF483","a":"ap","t":"","f":"Certo ou errado? A reforma da gestão pública de 1995 insti - tuiu na administração pública brasileira a dimensão gestão, a qual permitiu maior autonomia e introdução de novas formas de responsabilização para os gestores, como a administração por resultados, a competição administrada por excelência e o controle social.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TCE-PA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF484","a":"ce","t":"Serviços públicos e delegação (concessão, permissão, autorização)","f":"Certo ou errado? A criação das primeiras carreiras administrativas na administração pública e a busca pela adoção do concurso como forma de acesso ao serviço público são características do modelo de administração burocrática, implantado na década de 30 do século passado.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TCE-PA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF485","a":"ap","t":"","f":"Certo ou errado? C om o fim da ditadura militar, em 1985, e a retomada da democratização do Brasil, houve um significativo avanço na modernização da administração pública.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TCE-PA/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF486","a":"ap","t":"","f":"Certo ou errado? No modelo de administração pública patrimonial, os bens do Estado são administrados de forma pessoal, como se pertencessem ao próprio governante.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/FUB/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF487","a":"ap","t":"","f":"Certo ou errado? As práticas patrimonialistas, que consistem em administrar bens públicos como se fossem bens próprios, fazem parte do modelo gerencialista, defendido pela Nova Administração Pública.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/FUB/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF561","a":"ce","t":"Estado, governo e Administração Pública: conceitos e princípios","f":"Certo ou errado? Segundo o princípio da reserva legal, todas as pessoas, órgãos e entidades sujeitam-se às diversas espécies legislativas descritas na CF .","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/AGU/PROCURADOR FEDERAL/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF562","a":"ce","t":"Estado, governo e Administração Pública: conceitos e princípios","f":"Certo ou errado? A nomeação de cônjuge da autoridade nomeante para o exercício de cargo em comissão não afronta os princípios constitucionais.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DPE-ES/DEFENSOR PÚBLICO/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF563","a":"ce","t":"Estado, governo e Administração Pública: conceitos e princípios","f":"Certo ou errado? Como o direito administrativo disciplina, além da atividade do Poder Executivo, as atividades administrativas do Poder Judiciário e do Poder Legislativo, os princípios que regem a administração pública, previstos na CF , aplicam-se aos três poderes da República.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DPE-ES/DEFENSOR PÚBLICO/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF564","a":"ce","t":"Estado, governo e Administração Pública: conceitos e princípios","f":"Certo ou errado? De acordo com o princípio da publicidade, a administração deve divulgar informações de interesse público, sendo o sigilo dos atos administrativos admitido apenas excepcionalmente e se imprescindível à segurança da sociedade e do Estado.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DPE – ES/DEFENSOR PÚBLICO/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF565","a":"ce","t":"Estado, governo e Administração Pública: conceitos e princípios","f":"Certo ou errado? O conjunto das prerrogativas e restrições a que está sujeita a administração pública e que não se encontra nas relações entre particulares constitui o regime jurídico administrativo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PGE PE/ANALISTA JUDICIÁRIO DE PROCURADORIA/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF576","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? Para que um arquivo criado no Writer possa ser lido pelo Word, é suficiente marcar, na instalação do BrOffice.org, a opção que permite a compatibilidade entre essa suíte de aplicativos e o Microsoft Office.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/TRE-BA/TÉCNICO/2010 · selecionado via apostila Gran Cursos Online"},{"id":"LF577","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? Para se editar o cabeçalho de um documento no Writer, deve-se clicar o topo da página para abrir o espaço para edição. Por limitações técnicas desse editor de textos, não é possível colar textos ou imagens nesse espaço.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/INSS/TÉCNICO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF578","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? Por meio de recursos disponíveis no BrOffice Writer, é possível realizar cálculos complexos utilizando-se funções que podem ser inseridas nos campos de uma tabela.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/TC-RN/TÉCNICO/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF579","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? No Writer, é admissível continuar a pesquisa de determinada palavra em um documento, utilizando, simultaneamente, as teclas CTRL+ALT+F .","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/TELEBRAS/ESPECIALISTA/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF580","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? Para inserir, no BrOffice Writer, bordas em um documento, é correto adotar o seguinte procedimento: clicar o menu Inserir e, na lista disponibilizada, clicar a opção Bordas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MEC/TÉCNICO/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF581","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? O conteúdo de uma planilha eletrônica criada no Calc do BrOffice pode ser transferido para um documento em edição no Writer, sem que haja perda de informações.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SERPRO/TÉCNICO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF582","a":"inf","t":"Processador de textos (Word)","f":"Certo ou errado? O Impress e o Writer são aplicativos de edição de textos do Unix e, portanto, não podem ser utilizados em sistemas operacionais Windows.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CÂMARA FEDERAL/POL. LEGISLATIVO/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF583","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Um usuário que tenha instalado em seu computador um antivírus e um antispyware pode substituí-los por um firewall pessoal sem prejuízo à sua segurança, porque esse aplicativo possui recursos que tanto eliminam vírus quanto bloqueiam adware.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/EMBRAPEX/TÉCNICO/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF584","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Um firewall com portas abertas é um risco que pode ser explorado por um invasor para tirar vantagem de uma vulnerabilidade, o que gera impacto nos negócios.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/BANESE/TÉCNICO BANCÁRIO I/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF585","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Com relação às cópias de segurança, as mídias utilizadas não precisam ser periodicamente testadas, pois são usadas somente em caso de falha.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/BANESE/TÉCNICO BANCÁRIO I/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF586","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? O valor da informação é uma função do contexto da organização, da finalidade de utilização, do processo decisório e dos resultados das decisões","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/BANESE/TÉCNICO BANCÁRIO I/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF587","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Vírus é um pequeno programa de computador que propositalmente se replica e não depende de um usuário para se espalhar, uma vez que, quando ativado, se espalha automaticamente.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/BANESE/TÉCNICO BANCÁRIO I/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF588","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Para que as pragas virtuais denominadas worms ataquem o computador em uso, é necessário que se execute um arquivo do tipo.bat.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PC-DF/ESCRIVÃO DE POLÍCIA DA CARREIRA DE POLÍCIA CIVIL DO DISTRITO FEDERAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF589","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Os vírus do tipo cavalo de Troia, também conhecidos como trojans, podem ser instalados por outros vírus e programas, mas também podem infectar o ambiente por meio de links durante a navegação na Internet ou até mesmo por meio de emails falsos (phishing).","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DEPEN/CARGO 8 – AGENTE FEDERAL DE EXECUÇÃO PENAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF590","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Denomina-se backdoor a situação em que um usuário sofre um ataque, seus dados são criptografados, ficam inacessíveis e, então, exige-se desse usuário o pagamento de resgate para o restabelecimento do acesso a seus dados.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/POLICIA FEDERAL/ESCRIVÃO DE POLÍCIA FEDERAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF591","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Caso o usuário tenha recebido um conjunto de arquivos com trojan em seu conteúdo e esses arquivos estejam em uma mídia de armazenamento local em sua estação de trabalho, recomenda-se a utilização de IDS (intrusion detection system) para a realização da limpeza dos arquivos.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/POLICIA FEDERAL/ESCRIVÃO DE POLÍCIA FEDERAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF592","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Ransomware é um programa malicioso de computador que se propaga por meio da inserção de cópias de si mesmo em arquivos criptografados.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PRF/POLÍCIAL RODOVIÁRIA FEDERAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF593","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Spam é um tipo de e-mail que contém mensagem indesejada — como, por exemplo, propaganda de uma empresa — e que é enviado para um cliente sem a sua prévia solicitação ou autorização.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CODEVASF/ANALISTA EM DESEMVOLVIMENTO REGIONAL - ADMINISTRAÇÃO/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF594","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? O objetivo principal de um ataque DDoS é invadir bases de dados para coletar informações sensíveis; para isso, ele realiza a sobrecarga dos Melo recursos do servidor, por meio do envio de excessiva quantidade de requisições ou por meio da geração de grande tráfego de dados na rede.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/TCE.RJ/ANALISTA/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF595","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Os ataques de phishing caracterizam-se pelo envio de mensagens eletrônicas que despertam a atenção de usuários por meio da sugestão de vantagens ou ameaças de prejuízos e também por induzirem os usuários a fornecer dados pessoais e(ou) financeiros.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/TCE.RJ/ANALISTA/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF596","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Spam é um tipo de email que contém mensagem indesejada – como, por exemplo, propaganda de uma empresa – e que é enviado para um cliente sem a sua prévia solicitação ou autorização.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CODEVASF/COMUM/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF597","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? A instalação e a execução de um ou mais sistemas antimalware em um computador garantem proteção contra softwares maliciosos, mesmo que o usuário execute frequentemente arquivos recebidos em mensagens e não atualize seus programas e o sistema operacional.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/CODEVASF/T .I/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF598","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Nas redes sociais, ocorre a propagação de notícia falsa quando um usuário compartilha livremente conteúdo sem verificar a veracidade ou procedência das informações.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/ADV/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF599","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Nesse caso, utilizava-se a estratégia de phishing para obter dados dos usuários.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PC.SE/DELEGADO.INSTRUÇÃO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF600","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? O browser do computador da vítima provavelmente estava infectado por software malicioso que realizava um envenenamento de cache.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PC.SE/DELEGADO.INSTRUÇÃO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF601","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Integridade é a característica que garante o acesso à informação somente para quem estiver autorizado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/TÉCNICO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF602","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Honeypot é uma técnica pela qual um atacante utiliza um equipamento conectado à rede de computadores para tirar de operação um serviço, um computador ou toda uma rede conectada à Internet.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/TÉCNICO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF603","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Esteganografia é uma técnica que consiste em ocultar uma mensagem dentro da outra, enquanto a criptografia é uma técnica que codifica o conteúdo da mensagem.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/TÉCNICO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF604","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Os antivírus baseados em heurísticas são ferramentas antimalware que visam detectar e remover códigos maliciosos por meio de estruturas, instruções e características desses códigos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/TÉCNICO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF605","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? As ferramentas antispam coletam endereços de email mediante varreduras em páginas web e banco de dados, com vistas a proteger dados pessoais e financeiros do usuário, impedindo o fornecimento desses dados quando do acesso a páginas falsas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/TÉCNICO/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF606","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? A vinculação de uma chave privada a uma pessoa em particular é feita pela autoridade certificadora (AC), a qual, assim que verifica a identidade da pessoa, cria um certificado que vincula essa chave à pessoa e que, por segurança, não guarda a chave pública.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONÔMIA/T .I/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF607","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Identificação e autenticação são requisitos de segurança da informação que consistem em identificar usuários do sistema e verificar as suas identidades, como pré-requisito para permitir o acesso desses usuários ao sistema.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SEFAZ-AL/AUDITOR/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF608","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? A criptografia provê métodos de disfarçar informações; a criptografia de chave pública é simétrica quando envolve a utilização de duas chaves separadas, mas correlacionadas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SEFAZ-AL/AUDITOR/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF609","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? A assinatura digital foi desenvolvida especialmente com o objetivo de prover confidencialidade. Para criá-la, basta que o emissor gere um hash da mensagem enviada e cifre esse código hash com sua chave privada.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SEFAZ-DF/AUDITOR/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF610","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Em criptografia, denomina-se integridade a propriedade que garante que apenas o destinatário seja capaz de extrair o conteúdo da mensagem criptografada.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/T JAM/ASSISTENTE/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF611","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Os princípios fundamentais da segurança da informação incluem confidencialidade, integridade e disponibilidade. Os níveis de segurança para executar esses princípios em cada organização são os mesmos, considerando-se os objetivos e requisitos de negócio e de segurança.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/T JAM/ASSISTENTE/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF612","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? A segurança da informação nas organizações pode ser alcançada por meio da implementação de um conjunto adequado de controles, incluindo-se políticas, processos, procedimentos, estruturas organizacionais e funções de software e hardware.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/T JAM/ASSISTENTE/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF613","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Um certificado digital validado por uma autoridade certificadora permite associar uma mensagem ao seu remetente, garantindo-se, assim, a autenticidade da comunicação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/T JAM/ASSISTENTE/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF614","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Mateus tem em seu computador o Windows 10 e um firewall pessoal instalado que funciona corretamente. Nessa situação, embora esteja funcionando corretamente, o firewall não é suficiente para conter vírus e(ou) perdas de arquivos devidas a eventual falta de becape.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MPE-PI/TÉCNICO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF615","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? A superexposição de dados pessoais nas redes sociais facilita o furto de identidade ou a criação de identidade falsa com dados da vítima, identidades essas que podem ser usadas para atividades maliciosas tais como a realização de transações financeiras fraudulentas, a disseminação de códigos maliciosos e o envio de mensagens eletrônicas falsas por email ou redes sociais.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DPF/AGENTE/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF616","a":"inf","t":"Segurança da informação: senhas, autenticação, engenharia social, phishing","f":"Certo ou errado? Formatos comuns de arquivos, como, por exemplo,. docx ou.xlsx, são utilizados como vetor de infecção por ransomware, um tipo de software malicioso que encripta os dados do usuário e solicita resgate.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DPF/PERITO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF617","a":"inf","t":"Ameaças: vírus, worms, malware, ransomware","f":"Certo ou errado? No acesso a uma página web que contenha o código de um vírus de script, pode ocorrer a execução automática desse vírus, conforme as configurações do navegador.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/DPRF/AGENTE/2019 · selecionado via apostila Gran Cursos Online"},{"id":"LF618","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? O Windows 10 Enterprise gera uma ID de anúncio exclusiva para cada usuário em um dispositivo e, com base nessa ID e nas atividades dos usuários, é possível configurar o Windows para permitir que aplicativos forneçam anúncios mais relevantes.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SERIS.AL/AGENTE/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF619","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? Caso se deseje ter acesso remoto a todos os aplicativos e recursos de um computador conectado em rede, de forma similar ao que ocorre no acesso local, é possível fazê-lo por meio de recursos disponibilizados na área de trabalho remota do Windows 10.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PC-DF/ESCRIVÃO DE POLÍCIA/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF620","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? No Windows, ainda que seja possível compartilhar configurações — como plano de fundo e histórico de navegação do Internet Explorer — entre computadores que utilizem a mesma conta em outras máquinas com Windows 10, não é permitido, em razão da segurança, o compartilhamento de senhas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/PRF/POLICIAL RODOVIÁRIO FEDERAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF621","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? No Windows Explorer, os arquivos são elementos de armazenamento de informação, e as pastas são objetos para a organização dos arquivos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/MIN.ECONOMIA/ADV/2020 · selecionado via apostila Gran Cursos Online"},{"id":"LF622","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? O Windows 10 permite que o usuário configure as opções de becape para um disco de rede. Assim, o becape cópia, para o local definido, todo o conteúdo da pasta C:\\Users\\<username>, em que <username> equivale ao nome do usuário que configurou o becape.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/STJ/TÉCNICO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF623","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? O Windows 10 pode ser configurado para que, ao se clicar o menu Iniciar, seja disponibilizada uma lista de aplicativos instalados no computador, classificados em ordem alfabética.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CGM JOÃO PESSOA-PB/TÉCNICO/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF624","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? No Windows 10, arquivos podem ser compartilhados por meio do Explorador de Arquivos.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CORE-PR/ASSISTENTE ADMINISTRATIVO JÚNIOR/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF625","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? Com o programa Explorador de Arquivos do Windows 10, é possível visualizar algumas propriedades do arquivo, como, por exemplo, tamanho, data da criação, data de modificação, entre outras.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFONO – 4ª REGIÃO/FONOAUDIÓLOGO FISCAL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF626","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? Por meio do Explorador de Arquivos do Windows 10, é possível, em uma pasta, exibir uma lista de arquivos em ordem alfabética.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-AP/AGENTE ADMINISTRATIVO/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF627","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? Por meio do ícone , do Windows 10, é possível se configurar o teclado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRMV-AP/AGENTE ADMINISTRATIVO/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF628","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? Por meio do teclado virtual do Windows 10, o usuário poderá inserir letras, números ou símbolos em um documento.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRF-AP/ADMINISTRADOR/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF629","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? No Windows 10, ao se criar um usuário em um computador doméstico, é obrigatório informar uma senha.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRF-AP/ADMINISTRADOR/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF630","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? No caminho C:\\Downloads, extraído do Explorador de Arquivos do Windows 10, Downloads representa o nome de um arquivo, pois o nome que aparece após o caractere barra (/) sempre representa um arquivo no Windows.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CORE-TO/ASSISTENTE ADMINISTRATIVO/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF631","a":"inf","t":"Windows 10+: arquivos, pastas, programas e configurações","f":"Certo ou errado? No Windows 10, não é permitido criar dois arquivos com conteúdo exatamente igual, mesmo que possuam nomes diferentes, pois o Windows detecta esse tipo de anomalia e impede a criação de arquivos com conteúdo duplicado a fim de não sobrecarregar o sistema.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRT -04/AGENTE DE FISCALIZAÇÃO – EDIFICAÇÕES/CONSTRUÇÃO CI - VIL/2021 · selecionado via apostila Gran Cursos Online"},{"id":"LF632","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? No segmento “que venha a causar a diminuição”, o verbo auxiliar da locução verbal está conjugado no tempo presente do modo subjuntivo.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2021/CRESS/SE/ASSISTENTE SOCIAL/AGENTE FISCAL · selecionado via apostila Gran Cursos Online"},{"id":"LF633","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? Fica mantida a correção gramatical caso se altere a expressão “têm apontado” para vem apontando.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2021/CRF-AP/AGENTE DE SERVIÇOS GERAIS · selecionado via apostila Gran Cursos Online"},{"id":"LF634","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? O emprego das formas verbais “seja”, “batesse” e “dissesse” indica acontecimento certo e presente.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2019/CREFONO/9ª REGIÃO/FISCAL · selecionado via apostila Gran Cursos Online"},{"id":"LF635","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? A correção gramatical seria preservada caso a locução “vem ganhando” fosse substituída por tem ganhado.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE-CEBRASPE/2021/PG-DF/TÉCNICO JURÍDICO/APOIO ADMINISTRATIVO · selecionado via apostila Gran Cursos Online"},{"id":"LF636","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? Os sentidos e a correção gramatical seriam preservados se as locuções verbais “tinha levado” e “tinha pensado” fossem substituídas pelas formas verbais levara e pensara, respectivamente.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE-CEBRASPE/2021/PC-DF/ESCRIVÃO DE POLÍCIA DA CARREIRA DE POLÍCIA CIVIL DO DISTRITO FEDERAL · selecionado via apostila Gran Cursos Online"},{"id":"LF637","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? O emprego do subjuntivo em “que tenha” (l.1) confere à informação um caráter hipotético.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/2013/MPU/CONHECIMENTOS BÁSICOS PARA O CARGO 33 · selecionado via apostila Gran Cursos Online"},{"id":"LF638","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? A grafia “Numa” é correta e corresponde à contração da preposição em com o artigo uma.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE-CEBRASPE/2021/MPE-SC/PROMOTOR DE JUSTIÇA SUBSTITUTO/PROVA 2 · selecionado via apostila Gran Cursos Online"},{"id":"LF639","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? O vocábulo “num” (l.9) é formado pela contração da preposição em com o numeral um.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE-CEBRASPE/2019/PREFEITURA DE SÃO CRISTÓVÃO/SE/PROFESSOR DE EDUCA ­ ÇÃO BÁSICA/PORTUGUÊS · selecionado via apostila Gran Cursos Online"},{"id":"LF640","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? Quais as origens do folclore alagoano, quais os componentes culturais que o forjaram? Théo Brandão, com a autoridade de quem estudou a vida inteira e deixou uma obra irrepreensível sobre o assunto, diz que são muitas as contribuições na formatação do nosso folclore. Os vocábulos em destaque pertencem a mesma classe de palavras.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE-CEBRASPE/2021/PC-AL/ESCRIVÃO DE POLÍCIA/PROVA ANULADA · selecionado via apostila Gran Cursos Online"},{"id":"LF641","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? O termo “aos” é a soma da preposição “a” mais o artigo “os”.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2019/CRF/SE/ADMINISTRADOR · selecionado via apostila Gran Cursos Online"},{"id":"LF642","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? Nosso olhar não mudou. O vocábulo olhar classifica-se como verbo no contexto empregado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2019/ CRO-AM/ASSISTENTE ADMINISTRATIVO FISCAL · selecionado via apostila Gran Cursos Online"},{"id":"LF643","a":"lp","t":"Morfossintaxe: classes e formação de palavras, termos da oração","f":"Certo ou errado? O tinhoso chegou. O vocábulo tinhoso classifica-se como adjetivo no contexto empregado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2019/CRO-AM/ASSISTENTE ADMINISTRATIVO FISCAL · selecionado via apostila Gran Cursos Online"},{"id":"LF644","a":"lp","t":"Compreensão e interpretação de textos","f":"Certo ou errado? De 1991 a 2015, houve um aumento progressivo de casos de dengue no município de São José do Rio Preto, devido à resistência do mosquito Aedes aegypti às medidas implantadas para seu controle.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SUPERIOR/EBSERH/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF645","a":"lp","t":"Compreensão e interpretação de textos","f":"Certo ou errado? Na corrente predomina o uso de construções passivas para caracterizar os infortúnios decorrentes do descumprimento da mensagem.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/SUPERIOR/TCM-BA/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF646","a":"lp","t":"Compreensão e interpretação de textos","f":"Certo ou errado? Conclui-se do T exto, especialmente pelo emprego de “Incensurável” (l. 20), que seu autor considera correto o posicionamento de Kant sobre a dignidade humana.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/ANALISTA/ST J/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF647","a":"lp","t":"Compreensão e interpretação de textos","f":"Certo ou errado? A “estreita relação” (l. 5) entre o “vazamento” (l. 5) e a “espionagem” (l. 6) refere-se tanto ao objeto com que lidam seus agentes — informações sigilosas — quanto aos meios indevidos de que esses agentes se utilizam — para obter esse objeto, no caso da espionagem, e para torná-lo público, no caso do vazamento.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/AGENTE/ABIN/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF648","a":"lp","t":"Compreensão e interpretação de textos","f":"Certo ou errado? Na opinião do autor do T exto 1A10AAA, a carga tributária brasileira deveria ser menos regressiva.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CEBRASPE/AUDITOR/SEFAZ-RS/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF649","a":"lp","t":"Compreensão e interpretação de textos","f":"Certo ou errado? Nas linhas de 12 a 14, Carolina pede que Carlinhos não empregue certos vocábulos da língua portuguesa porque esses são considerados como arcaicos pela gramática normativa da língua.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/PROFESSOR L. PORTUGUESA/SEDF/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF650","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? A conjunção “se” é usada com valor condicional. “Em todos esses casos, é fundamental desconfiar de ofertas exorbitantes, procurar avaliações de usuários, verificar se a empresa possui canais de atendimento e está devidamente registrada na Receita Federal, entre outras precauções.”","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2023/PROCON-DF/FISCAL DE DEFESA DO CONSUMIDOR · selecionado via apostila Gran Cursos Online"},{"id":"LF651","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? A partícula “se” , em “a equipe concentrouse” , indica que o sujeito da oração é indeterminado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2023/CRA-PE/ADMINISTRADOR · selecionado via apostila Gran Cursos Online"},{"id":"LF652","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? Na oração “as cidades devem posicionar-se de forma diferente no novo milênio” , conclui-se do emprego do vocábulo “se” que a oração está na voz passiva, isto é, a locução “devem posicionar-se” é, sintática e semanticamente, equivalente a devem ser posicionadas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CEBRASPE/2022/TCE-RJ/TÉCNICO DE CONTROLE EXTERNO · selecionado via apostila Gran Cursos Online"},{"id":"LF653","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? Em “nos dias que se seguiram ao terremoto que devastou o Haiti” , a colocação do pronome “se” antes da forma verbal justifica-se para reforçar a indeterminação do sujeito oracional.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CEBRASPE/2022/TELEBRAS/ESPECIALISTA EM GESTÃO DE TELECOMUNICAÇÕES/ AUDITORIA · selecionado via apostila Gran Cursos Online"},{"id":"LF654","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? A partícula “se” em “Estáse aqui, sozinho, sentado à mesa” funciona como índice de indeterminação do sujeito.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"IADES/2021/INSTITUTO RIO BRANCO/DIPLOMATA/MANHÃ · selecionado via apostila Gran Cursos Online"},{"id":"LF655","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? Na forma verbal “Cogita-se [uma mudança de modelo econômico]” , a partícula “se” indica que o sujeito da oração é indeterminado.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2021/CORE-TO/ASSISTENTE ADMINISTRATIVO · selecionado via apostila Gran Cursos Online"},{"id":"LF656","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? O emprego da partícula “se” , em “prezando-se” , indica que o sujeito da oração é indeterminado. “Com o passar dos anos, novas tendências odontológicas foram surgindo, prezando-se o bem-estar dos pacientes.”","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/2020/CRO-DF/FISCAL I · selecionado via apostila Gran Cursos Online"},{"id":"LF657","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego do acento gráfico nas palavras “Dói”, “só” e “nós” justifica-se pela mesma regra de acentuação.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/POLÍCIA MILITAR DE ALAGOAS/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF658","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os vocábulos “trás”, “é” e “nós” recebem acento gráfico em obe - diência à mesma regra de acentuação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/BNB/2018 · selecionado via apostila Gran Cursos Online"},{"id":"LF659","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Julgue: As formas verbais “torná-la” e “fazêla” recebem acentuação gráfica porque se devem acentuar todas as formas verbais combinadas a pronome enclítico.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/PC-GO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF660","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Julgue: A mesma regra de acentuação justifica o emprego de acento em “à” e “é”.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/PC-GO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF661","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? A palavra “está” recebe acento gráfico em decorrência da mesma regra que determina o emprego do acento no vocábulo “três”.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TELEBRÁS/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF662","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “pó”, “só” e “céu” são acentuadas de acordo com a mesma regra de acentuação gráfica.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/IBAMA/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF663","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O arquiteto Oscar Niemeyer transformou as ideias em prédios. A ausência de acento agudo em “ideias” está em conformidade com as regras ortográficas vigentes.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/FUB/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF664","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As formas “patrimônio” e “polícia” são acentuadas em decorrência da mesma regra de acentuação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/PRF/NÍVEL SUPERIOR/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF665","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os vocábulos “caráter”, “intransferível” e “órgãos” são acentuados em decorrência da regra gramatical que classifica as palavras paroxítonas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/DEFENSORIA PÚBLICA DA UNIÃO/2016 · selecionado via apostila Gran Cursos Online"},{"id":"LF666","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “líquida”, “público” e “órgãos” obedecem à mesma regra de acentuação gráfica.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUDITOR DO TCU/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF667","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os acentos gráficos das palavras “bioestatística” e “específicos” têm a mesma justificativa gramatical.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/FUB/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF668","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego de acento na palavra “memória” pode ser justificado por duas regras de acentuação distintas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TRF - 1ª REGIÃO/ANALISTA/2017 · selecionado via apostila Gran Cursos Online"},{"id":"LF669","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego do acento gráfico em “remédios” pode ser justificado com base em duas regras distintas de acentuação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/STF/ANALISTA JUDICIÁRIO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF670","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? A regra de acentuação gráfica que justifica o emprego do acento gráfico em “aeroportuário” é a mesma que justifica o emprego do acento em “meteorológica”","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/SUPREMO TRIBUNAL MILITAR/2011 · selecionado via apostila Gran Cursos Online"},{"id":"LF671","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “Polícia”, “Rodoviária” e “existência” recebem acento gráfico porque são paroxítonas terminadas em ditongo crescente.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/PRF/AGENTE ADMINISTRATIVO/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF672","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os acentos gráficos das palavras “países” e “políticas” têm a mesma justificativa gramatical.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/FUB/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF673","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os vocábulos “juízes” e “país” são acentuados de acordo com regras de acentuação gráfica distintas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TRT 17ª REGIÃO/TÉCNICO JUDICIÁRIO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF676","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os vocábulos “assistência”, “potável” e “elétrica” são acentuados de acordo com a mesma regra de acentuação gráfica.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AUFC/CONTROLE EXTERNO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF677","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? A mesma regra de acentuação gráfica justifica o emprego de acento gráfico nas palavras “construída” e “possíveis”.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CONSELHO NACIONAL DE JUSTIÇA/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF678","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “países”, “famílias” e “níveis” são acentuadas de acordo com a mesma regra de acentuação gráfica.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TRT DF E TO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF679","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “Penitenciário”, “carcerária” e “Judiciário” recebem acento gráfico com base na mesma regra gramatical.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/DEPEN/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF680","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? A ocorrência de hiato justifica o emprego do acento agudo nas vogais i e u nas palavras “construída” e “conteúdos”.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CPRM/GEOLOGIA/2015 · selecionado via apostila Gran Cursos Online"},{"id":"LF681","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “providências” e “fortalecê-los” recebem acento gráfico com base em regras gramaticais diferentes.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ TCE RO/2013 · selecionado via apostila Gran Cursos Online"},{"id":"LF682","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? A palavra “prejuízos” recebe acento gráfico porque todas as proparoxítonas devem ser acentuadas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/SUFRAMA/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF683","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego do acento gráfico em “incluíram” e “número” justifica-se com base na mesma regra de acentuação.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CAIXA ECONÔMICA FEDERAL/MÉDICO/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF684","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego do acento gráfico na palavra “atrás” justifica-se com base na mesma regra que justifica o emprego do acento gráfico em “fiéis”","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/PM-CE/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF685","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? A mesma regra de acentuação gráfica se aplica aos vocábulos “Brasília”, “cenário” e “próprio”.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ICMBIO/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF686","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os vocábulos “sabíamos” e “procurávamos” recebem a mesma regra de acentuação gráfica.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/AG. ADM./CADE/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF687","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego do acento gráfico em “indústria” e “rádio” justifica-se com base na mesma regra de acentuação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANATEL/ADMINISTRATIVO/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF688","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os termos “série” e “história” acentuam-se em conformidade com a mesma regra ortográfica.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/POLÍCIA FEDERAL/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF689","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? O emprego de acento gráfico em “água”, “distância” e “primário” justifica-se pela mesma regra de acentuação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANTAQ/2014 · selecionado via apostila Gran Cursos Online"},{"id":"LF690","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os vocábulos “analítica” e “teríamos” recebem acento gráfico com base na mesma regra de acentuação.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/TJ-ES/2011 · selecionado via apostila Gran Cursos Online"},{"id":"LF691","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? As palavras “início” e “série” recebem acento gráfico com base em regras gramaticais distintas.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANAC/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF692","a":"lp","t":"Ortografia oficial e acentuação gráfica","f":"Certo ou errado? Os termos “Três” e “Vã” são acentuados em decorrência de igual justificativa gramatical.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/ANAC/2012 · selecionado via apostila Gran Cursos Online"},{"id":"LF693","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? Uma oração subordinada pode ter função de complemento nominal, nesse caso será classificada como subordinada substantiva completiva nominal, como é o caso da oração subordinada em Tinha necessidade de que me ajudassem a subir as escadas.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"INSTITUTO CONSULPLAN/2019/MPE-SC/PROMOTOR DE JUSTIÇA/VESPERTINA · selecionado via apostila Gran Cursos Online"},{"id":"LF694","a":"lp","t":"Coordenação, subordinação, vozes verbais e pronomes relativos","f":"Certo ou errado? A palavra “se” (l.5) classifica-se como conjunção e introduz uma oração completiva.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/2018/STM/ANALISTA JUDICIÁRIO/REVISÃO DE TEXTO · selecionado via apostila Gran Cursos Online"},{"id":"LF695","a":"lp","t":"Pontuação e efeitos de sentido","f":"Certo ou errado? O emprego do sinal de dois-pontos após o vocábulo “Live” e a ausência de ponto final após a palavra “adequada” prejudicam a coerência da mensagem.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRM-SC/REVISOR DE TEXTO/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF696","a":"lp","t":"Pontuação e efeitos de sentido","f":"Certo ou errado? As vírgulas empregadas após “Em 2013” e “Ao longo dos anos” têm uso facultativo.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRP 11ª REGIÃO/ASSISTENTE ADMINISTRATIVO/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF697","a":"lp","t":"Pontuação e efeitos de sentido","f":"Certo ou errado? A vírgula empregada após Ishida é obrigatória, pois desloca oração de valor conformativo.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFITO 10ª REGIÃO/AGENTE FISCAL/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF698","a":"lp","t":"Pontuação e efeitos de sentido","f":"Certo ou errado? A vírgula empregada após “Aos 82 anos de idades” é obrigatória.","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CRECI 11ª REGIÃO/CONTADOR/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF699","a":"lp","t":"Pontuação e efeitos de sentido","f":"Certo ou errado? Apesar dos feitos extraordinários da ciência e dos investimentos públicos em ciência e tecnologia, verifica-se uma espécie de movimento de deslegitimação social do conhecimento científico no mundo todo. A vírgula empregada após “tecnologia” é facultativa.","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CEBRASPE/MC/ATIVIDADES TÉCNICAS DE COMPLEXIDADE INTELECTUAL/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF700","a":"lp","t":"Pontuação e efeitos de sentido","f":"Certo ou errado? Em ‘Acho que não podia ser mais claro’ , a correção gramatical seria prejudicada caso se inserisse uma vírgula logo após ‘Acho’ .","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"CESPE/CEBRASPE/TELEBRAS/ESPECIALISTA EM GESTÃO DE TELECOMUNICAÇÕES/2022 · selecionado via apostila Gran Cursos Online"},{"id":"LF701","a":"lp","t":"Regência verbal e nominal","f":"Certo ou errado? Quanto ao emprego do acento indicativo de crase, a substituição de “formação continuada” por formações continuadas eliminaria o acento. “O Conselho de Arquitetura e Urbanismo do Brasil (CAU-BR) lançou, em março, um novo portal on-line, com um conteúdo dedicado à formação continuada do profissional de arquitetura e urbanismo.”","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CAU-PA/ARQUITETO E URBANISTA/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF702","a":"lp","t":"Regência verbal e nominal","f":"Certo ou errado? O emprego do acento grave em “à reclamação relatada” é obrigatório. “O consumidor, por sua vez, deve se identificar adequadamente, comprometendo-se a apresentar todos os dados e todas as informações relativas à reclamação relatada.”","v":"CERTO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/PROCON-DF/ANALISTA DE ATIVIDADES DE DEFESA DO CONSUMIDOR – ADMINISTRAÇÃO/2023 · selecionado via apostila Gran Cursos Online"},{"id":"LF703","a":"lp","t":"Regência verbal e nominal","f":"Certo ou errado? O emprego do sinal indicativo de crase nas duas ocorrências de contração “às” é facultativo. “Abrange os aspectos referentes à linguagem oral, escrita e sinalizada, à fluência, à articulação da fala, à voz, às estruturas e às funções orofaciais (respiração, mastigação e deglutição), às funções auditiva e vestibular (equilíbrio) e aos sistemas de comunicação alternativos, aumentativos ou suplementares, entre outros.”","v":"ERRADO. (gabarito oficial)","orig":"ce","fonte":"QUADRIX/CREFONO-2/ANALISTA DE FISCALIZAÇÃO E INSPETORIA/2023 · selecionado via apostila Gran Cursos Online"}];
